// Initialization of needed variables
int Counter =  0;
boolean Direction;
int Pin_clk_Last;
int Pin_clk_Current;
// Definition of input pins
int pin_clk =  3;
int pin_dt =  4;
int button_pin =  5;
void setup() {
  // Initialize input pins...
  pinMode(pin_clk, INPUT);
  pinMode(pin_dt, INPUT);
  pinMode(button_pin, INPUT);
  // ...and activate their pull-up resistors
  digitalWrite(pin_clk, true);
  digitalWrite(pin_dt, true);
  digitalWrite(button_pin, true);
  // Initial reading of Pin_CLK
  Pin_clk_Last = digitalRead(pin_clk);
  Serial.begin(115200);
}
/*
The program checks if there has been a change in the pin states, which of 
the two
pins changed first, indicating the direction of rotation.
This information is obtained by comparing one of the pin values from a 
previous
run with the value of the current run.
Once the direction is determined, steps are counted from the start 
position and displayed.
Pressing the button on the rotary encoder resets the current position.
*/

void loop() {
  // Read the current status
  Pin_clk_Current = digitalRead(pin_clk);
  // Check for change
 if (Pin_clk_Current != Pin_clk_Last) {
   if (digitalRead(pin_dt) != Pin_clk_Current) {
      // Pin_CLK changed first
      Counter++;
      Direction = true;
    }
   else {  // Otherwise, Pin_DT changed first
      Direction = false;
      Counter--;
    }
    Serial.println("Rotation detected: ");
    Serial.print("Rotation direction: ");
   if (Direction) {
      Serial.println("Clockwise");
    } else {
      Serial.println("Counterclockwise");
    }
    Serial.print("Current position: ");
    Serial.println(Counter);
    Serial.println("------------------------------");
  }
  /* 
  Preparation for the next run:
  The value of the current run is the previous value in the next run
  */
  Pin_clk_Last = Pin_clk_Current;
  // Reset function to save the current position
 if (!digitalRead(button_pin) && Counter != 0) {
    Counter = 0;
    Serial.println("Position reset");
  }
}
